    double angle = 2 * CGAL::Pi * i / numberOfChecks;
    Point3d direction(std::cos(angle), std::sin(angle), 0);
    Ray3d ray(p, direction);
    int intersections = 0;
    for (const auto& face : faces) {
        if (CGAL::do_intersect(ray, tree.triangle(face[0], face[1], face[2]))) {
            intersections++;
        }
    }
    if (intersections % 2 == 1) {
        count++;
    }
}
return count == numberOfChecks;

